const $ = s => document.querySelector(s);
let meetings = [];
try { const storedMeetings = JSON.parse(localStorage.getItem('meeting-note-data') || '[]'); meetings = Array.isArray(storedMeetings) ? storedMeetings.filter(m=>m&&typeof m==='object').map(m=>({...m,title:String(m.title||''),location:String(m.location||''),note:String(m.note||''),agenda:Array.isArray(m.agenda)?m.agenda:[],photos:Array.isArray(m.photos)?m.photos:[],stakeholders:Array.isArray(m.stakeholders)?m.stakeholders:[]})) : []; } catch { meetings = []; }
let current, activeTab = 'note', recorder, chunks = [], timer, elapsed = 0, deferredPrompt;
const persist = () => {
  try { localStorage.setItem('meeting-note-data', JSON.stringify(meetings)); }
  catch (err) {
    try { localStorage.setItem('meeting-note-data', JSON.stringify(meetings.map(m => ({ ...m, audio: null, photos: [] })))); }
    catch { console.warn('Meeting data is stored in IndexedDB; localStorage backup is full.', err); }
  }
  window.ZMinutesStore?.put('meetings', meetings).catch(err => console.error('IndexedDB meeting save failed', err));
  const state = $('#saveState'); if (state) state.textContent = 'Saved';
};
const uid = () => crypto.randomUUID();
const nowLocal = () => { const d = new Date(); d.setMinutes(d.getMinutes() - d.getTimezoneOffset()); return d.toISOString().slice(0,16); };
const esc = s => String(s || '').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function formatDate(v){ if(!v) return 'Not scheduled'; const d=new Date(v); return d.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})+' · '+d.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}); }
function renderHome(query=''){
  const list=$('#meetingList'); const filtered=meetings.filter(m=>(m.title+m.location).toLowerCase().includes(query.toLowerCase()));
  $('#meetingCount').textContent=meetings.length?`${meetings.length} meeting${meetings.length===1?'':'s'} saved on this device`:'No meetings yet'; list.innerHTML='';
  if(!filtered.length){list.innerHTML='<div class="muted">No meetings found. Create a new meeting to get started.</div>';return;}
  filtered.sort((a,b)=>b.updated-a.updated).forEach(m=>{const t=$('#meetingTemplate').content.cloneNode(true); const a=t.querySelector('.card-main');t.querySelector('.meeting-date').textContent=new Date(m.date||Date.now()).toLocaleDateString('en-US',{day:'2-digit',month:'short'});t.querySelector('strong').textContent=m.title||'Untitled meeting';t.querySelector('small').textContent=formatDate(m.date);a.onclick=()=>openMeeting(m.id);t.querySelector('.delete-btn').onclick=e=>{e.stopPropagation();if(confirm(`Delete “${m.title}”?`)){meetings=meetings.filter(x=>x.id!==m.id);persist();renderHome($('#searchInput').value);}};list.append(t);});
}
function newMeeting(title='',date=nowLocal()) { const m={id:uid(),title,date,location:'',note:'',agenda:[],photos:[],stakeholders:[],transcript:'',summary:'',updated:Date.now(),audio:null};meetings.push(m);persist();openMeeting(m.id); }
function openMeeting(id){current=meetings.find(m=>m.id===id); if(!current)return; $('#homeView').classList.add('hidden');$('#editorView').classList.remove('hidden');$('#backBtn').classList.remove('hidden');$('#newMeetingBtn').classList.add('hidden'); $('#titleInput').value=current.title;$('#dateInput').value=current.date||'';$('#locationInput').value=current.location||'';$('#noteInput').value=current.note||''; renderEditor();}
function saveCurrent(){if(!current)return;current.title=$('#titleInput').value.trim()||'Untitled meeting';current.date=$('#dateInput').value;current.location=$('#locationInput').value;current.note=$('#noteInput').value;current.updated=Date.now();persist();}
function renderEditor(){
  $('#agendaBadge').textContent=current.agenda.length;$('#photoBadge').textContent=current.photos.length;renderAgenda();renderPhotos();renderSummary();document.querySelectorAll('.tabs [data-tab]').forEach(b=>{const selected=b.dataset.tab===activeTab;b.classList.toggle('active',selected);b.setAttribute('aria-selected',String(selected));});['note','agenda','field','summary','stakeholders'].forEach(x=>$('#'+x+'Panel')?.classList.toggle('hidden',x!==activeTab));
}
function renderAgenda(){const box=$('#agendaList');box.innerHTML='';current.agenda.forEach(a=>{const item=document.createElement('div');item.className='agenda-item'+(a.done?' done':'');item.innerHTML=`<input type="checkbox" ${a.done?'checked':''}><label>${esc(a.text)}</label><button class="remove" aria-label="Remove question">×</button><textarea class="agenda-note" placeholder="Notes, answer, or follow-up for this question…">${esc(a.note||'')}</textarea>`;item.querySelector('input').onchange=e=>{a.done=e.target.checked;saveCurrent();renderAgenda();};item.querySelector('.agenda-note').oninput=e=>{a.note=e.target.value;saveCurrent();};item.querySelector('.remove').onclick=()=>{current.agenda=current.agenda.filter(x=>x.id!==a.id);saveCurrent();renderEditor();};box.append(item);});}
function renderPhotos(){const grid=$('#photoList');grid.innerHTML='';current.photos.forEach(p=>{const card=document.createElement('div');card.className='photo-card';card.innerHTML=`<img src="${p.data}" alt="Ảnh hiện trường"><textarea placeholder="Ghi chú cho ảnh này…">${esc(p.note||'')}</textarea>`;card.querySelector('textarea').oninput=e=>{p.note=e.target.value;saveCurrent();};grid.append(card);});}
function renderSummary(){const o=$('#summaryOutput');if(!current.summary){o.className='summary-output empty';o.innerHTML='<p>Chưa có tóm tắt. Khi xong cuộc họp, bấm “Tạo tóm tắt”.</p>';return;}o.className='summary-output';o.innerHTML=current.summary;}
function generateQuickSummary(){const lines=current.note.split('\n').map(x=>x.trim()).filter(Boolean);const decisions=lines.filter(x=>/decision|◇/i.test(x));const tasks=lines.filter(x=>/action item|✓|todo|deadline/i.test(x));const agenda=current.agenda;const bullets=a=>a.length?`<ul>${a.map(x=>`<li>${esc(typeof x==='string'?x:x.text)}</li>`).join('')}</ul>`:'<p>Nothing captured yet.</p>';
 current.summary=`<h3>Overview</h3><p>${esc(lines.slice(0,3).join(' ')||'No detailed meeting notes have been added yet.')}</p><h3>Decisions</h3>${bullets(decisions)}<h3>Action items</h3>${bullets(tasks)}<h3>Agenda / questions</h3>${bullets(agenda)}<h3>Field notes</h3><p>${current.photos.length?`${current.photos.length} field photo${current.photos.length===1?' was':'s were'} added.`:'No field photos were added.'}</p>`;saveCurrent();renderSummary();}
async function generateSummary(){saveCurrent();const button=$('#generateSummaryBtn'), provider=$('#aiProvider').value, model=$('#aiModel').value.trim(), key=$('#aiApiKey').value.trim(), url=$('#ollamaUrl').value.trim().replace(/\/$/,''), prompt=`You are a precise meeting assistant. Write a concise meeting recap in English as HTML only, using h3, p and ul tags. Include exactly these sections when applicable: Overview, Decisions, Action items, Open questions, Field notes. Do not invent facts.\n\nMeeting title: ${current.title}\nDate: ${formatDate(current.date)}\nAgenda:\n${current.agenda.map(a=>`- ${a.text}${a.note?` (note: ${a.note})`:''}`).join('\n')||'None'}\n\nNotes:\n${current.note||'None'}\n\nField photos: ${current.photos.length}`;
  localStorage.setItem('meeting-note-ai',JSON.stringify({provider,model,url}));if(provider==='quick'){generateQuickSummary();$('#aiStatus').textContent='Quick local draft';return;}if(!key && provider!=='ollama'){alert('Paste an API key in AI settings first.');return;}button.disabled=true;button.textContent='Generating…';$('#aiStatus').textContent=`Connecting to ${provider==='openai'?'OpenAI':provider==='gemini'?'Gemini':'Ollama'}…`;try{let res,data,output;if(provider==='gemini'){res=await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`,{method:'POST',headers:{'Content-Type':'application/json','x-goog-api-key':key},body:JSON.stringify({contents:[{parts:[{text:prompt}]}],generationConfig:{temperature:0.2}})});data=await res.json();if(!res.ok)throw new Error(data.error?.message||`Gemini returned ${res.status}`);output=data.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('');}else if(provider==='openai'){res=await fetch('https://api.openai.com/v1/responses',{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${key}`},body:JSON.stringify({model,input:prompt,temperature:0.2})});data=await res.json();if(!res.ok)throw new Error(data.error?.message||`OpenAI returned ${res.status}`);output=data.output_text||data.output?.flatMap(x=>x.content||[]).map(x=>x.text||'').join('');}else{res=await fetch(`${url}/api/generate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model,prompt,stream:false,options:{temperature:0.2}})});data=await res.json();if(!res.ok)throw new Error(data.error||`Ollama returned ${res.status}`);output=data.response;}output=String(output||'').replace(/```html|```/g,'').trim();if(!output)throw new Error('No recap returned');current.summary=output;saveCurrent();renderSummary();$('#aiStatus').textContent=`Generated with ${model}`;}catch(err){console.warn(err);alert(`AI recap failed: ${err.message}`);generateQuickSummary();$('#aiStatus').textContent='AI unavailable — quick local draft used';}finally{button.disabled=false;button.textContent='✦ Generate recap';}}
function switchTab(tab){if(!current||!['note','agenda','stakeholders','field','summary'].includes(tab))return;activeTab=tab;renderEditor();}
function insertQuick(type){const notes=$('#noteInput');const prefix={decision:'◇ DECISION: ',task:'✓ ACTION ITEM: ',important:'! IMPORTANT: '}[type];const at=notes.selectionStart;notes.setRangeText(`\n${prefix}`,at,notes.selectionEnd,'end');notes.focus();saveCurrent();}
function formatTime(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
async function toggleRecord(){if(recorder?.state==='recording'){recorder.stop();return;}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());clearInterval(timer);$('#recordDot').classList.remove('live');$('#recordLabel').textContent='Audio saved locally';$('#recordBtn').classList.remove('live');$('#recordBtn span').textContent='Record';const blob=new Blob(chunks,{type:'audio/webm'});const reader=new FileReader();reader.onload=()=>{current.audio=reader.result;saveCurrent();$('#transcriptText').textContent='Audio is saved with this meeting. Connect local Whisper to generate a transcript.';};reader.readAsDataURL(blob);};recorder.start();elapsed=0;$('#recordDot').classList.add('live');$('#recordLabel').textContent='Recording';$('#recordBtn').classList.add('live');$('#recordBtn span').textContent='Stop';timer=setInterval(()=>{$('#recordTimer').textContent=formatTime(++elapsed)},1000);}catch(e){alert('Microphone access is unavailable. Allow microphone access, then try again.');}}
function exportDoc(){saveCurrent();const body=`<h1>${esc(current.title)}</h1><p>${esc(formatDate(current.date))} — ${esc(current.location)}</p><h2>Ghi chú</h2><pre>${esc(current.note)}</pre><h2>Agenda</h2><ul>${current.agenda.map(x=>`<li>${esc(x.text)}</li>`).join('')}</ul><h2>Tóm tắt</h2>${current.summary||'<p>Chưa tạo tóm tắt.</p>'}`;const blob=new Blob([`<html><head><meta charset="utf-8"><title>${esc(current.title)}</title></head><body>${body}</body></html>`],{type:'application/msword'});download(blob,`${safeName(current.title)}.doc`);}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}function safeName(s){return (s||'meeting-note').replace(/[\\/:*?"<>|]/g,'-');}
function exportPackage(){saveCurrent();const copy=structuredClone(current);copy.exportedAt=new Date().toISOString();copy.format='meeting-note-package-v1';download(new Blob([JSON.stringify(copy,null,2)],{type:'application/json'}),`${safeName(current.title)}.meeting.json`);}
function importPackage(file){const reader=new FileReader();reader.onload=()=>{try{const imported=JSON.parse(reader.result);if(!imported || typeof imported!=='object' || !('title' in imported))throw new Error('Invalid package');const meeting={id:uid(),title:imported.title||'Imported meeting',date:imported.date||nowLocal(),location:imported.location||'',note:imported.note||'',agenda:Array.isArray(imported.agenda)?imported.agenda:[],photos:Array.isArray(imported.photos)?imported.photos:[],summary:imported.summary||'',updated:Date.now(),audio:imported.audio||null};meetings.push(meeting);persist();renderHome();alert('Meeting imported successfully.');}catch(e){alert('This file is not a valid Meeting Notes package.');}};reader.readAsText(file);}
function pdfText(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^\x20-\x7e]/g,' ').replace(/[\\()]/g,'\\$&');}
function wrapPdf(text,width=88){const words=pdfText(text).split(/\s+/);const lines=[];let line='';for(const word of words){if((line+' '+word).trim().length>width){if(line)lines.push(line);line=word;}else line=(line+' '+word).trim();}if(line)lines.push(line);return lines;}
function exportPdf(){saveCurrent();const content=[['MEETING NOTES',18],['',10],[current.title,16],[formatDate(current.date),10],[current.location,10],['',10],['NOTES',13],...wrapPdf(current.note||'No notes added.').map(x=>[x,10]),['',10],['AGENDA',13],...current.agenda.flatMap(a=>wrapPdf(`- ${a.done?'[done] ':''}${a.text}`).map(x=>[x,10])),['',10],['MEETING RECAP',13],...wrapPdf(strip(current.summary)||'No recap generated.').map(x=>[x,10])];let y=790,streams=[],pages=[];for(const [text,size] of content){if(y<55){pages.push(streams.join('\n'));streams=[];y=790;}streams.push(`BT /F1 ${size} Tf 50 ${y} Td (${pdfText(text)}) Tj ET`);y-=size+7;}pages.push(streams.join('\n'));let objects=['<< /Type /Catalog /Pages 2 0 R >>',''];const pageIds=[];for(const stream of pages){const id=objects.length+1;pageIds.push(id);objects.push(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`);objects.push('');}const fontId=objects.length+1;objects.push('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');const pageObjectIds=[];for(let i=0;i<pageIds.length;i++){pageObjectIds.push(objects.length+1);objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 ${fontId} 0 R >> >> /Contents ${pageIds[i]} 0 R >>`);}objects[1]=`<< /Type /Pages /Kids [${pageObjectIds.map(id=>id+' 0 R').join(' ')}] /Count ${pageObjectIds.length} >>`;let pdf='%PDF-1.4\n',offsets=[0];objects.forEach((o,i)=>{offsets.push(pdf.length);pdf+=`${i+1} 0 obj\n${o}\nendobj\n`;});const start=pdf.length;pdf+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n${offsets.slice(1).map(x=>String(x).padStart(10,'0')+' 00000 n ').join('\n')}\ntrailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`;download(new Blob([pdf],{type:'application/pdf'}),`${safeName(current.title)}.pdf`);}
function strip(html){const x=document.createElement('div');x.innerHTML=html;return x.innerText;}
function share(){const text=`${current.title}\n${formatDate(current.date)}\n\n${current.note}\n\n${strip(current.summary)}`;navigator.share?navigator.share({title:current.title,text}).catch(()=>{}):navigator.clipboard.writeText(text).then(()=>alert('Meeting notes copied to the clipboard.'));}
const savedAi=JSON.parse(localStorage.getItem('meeting-note-ai')||'{}');if(savedAi.url)$('#ollamaUrl').value=savedAi.url;if(savedAi.model)$('#aiModel').value=savedAi.model;if(savedAi.provider){$('#aiProvider').value=savedAi.provider;$('#aiModel').dataset.provider=savedAi.provider;}
function refreshAiFields(){const p=$('#aiProvider').value, local=p==='ollama', quick=p==='quick';$('#apiKeyField').classList.toggle('hidden',local||quick);$('#ollamaUrlField').classList.toggle('hidden',!local);const defaults={gemini:'gemini-2.5-flash',openai:'gpt-4.1-mini',ollama:'qwen2.5:3b',quick:''};if(!$('#aiModel').value || $('#aiModel').dataset.provider!==p){$('#aiModel').value=defaults[p];$('#aiModel').dataset.provider=p;}$('#aiHelp').textContent=quick?'No API request will be made. The app creates a quick draft from your notes.':local?'Runs against Ollama installed on this device. A small 3B model is suggested for lighter laptops.':p==='gemini'?'Use a Gemini API key from Google AI Studio. Your key stays only in this browser on this device.':'Use an OpenAI API key. ChatGPT subscriptions and API billing are separate.';}
refreshAiFields();$('#aiProvider').onchange=refreshAiFields;
$('#newMeetingBtn').onclick=()=>$('#newMeetingDialog').showModal();$('#heroNewBtn').onclick=()=>$('#newMeetingDialog').showModal();$('#importMeetingBtn').onclick=()=>$('#importMeetingInput').click();$('#importMeetingInput').onchange=e=>{if(e.target.files[0])importPackage(e.target.files[0]);e.target.value='';};$('#newMeetingForm').onsubmit=e=>{e.preventDefault();newMeeting($('#newTitle').value,$('#newDate').value||nowLocal());$('#newMeetingDialog').close();$('#newMeetingForm').reset();};$('#backBtn').onclick=()=>{saveCurrent();current=null;$('#editorView').classList.add('hidden');$('#homeView').classList.remove('hidden');$('#backBtn').classList.add('hidden');$('#newMeetingBtn').classList.remove('hidden');renderHome();};$('#searchInput').oninput=e=>renderHome(e.target.value);['titleInput','dateInput','locationInput','noteInput'].forEach(id=>$('#'+id).oninput=()=>{ $('#saveState').textContent='Saving…';saveCurrent();});$('.tabs').addEventListener('click',e=>{const button=e.target.closest('[data-tab]');if(button){e.preventDefault();switchTab(button.dataset.tab);}});$('#agendaForm').onsubmit=e=>{e.preventDefault();const input=$('#agendaInput');if(input.value.trim()){current.agenda.push({id:uid(),text:input.value.trim(),note:'',done:false});input.value='';saveCurrent();renderEditor();}};$('#agendaUpload').onchange=e=>{const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{const lines=String(reader.result).split(/\r?\n|,/).map(x=>x.trim().replace(/^[-•\d.]+\s*/, '')).filter(Boolean);if(!lines.length){alert('No questions found in this file.');return;}current.agenda.push(...lines.map(text=>({id:uid(),text,note:'',done:false})));saveCurrent();renderEditor();alert(`${lines.length} question${lines.length===1?'':'s'} imported.`);};reader.readAsText(file);e.target.value='';};document.querySelectorAll('.quick').forEach(b=>b.onclick=()=>insertQuick(b.dataset.insert));$('#photoInput').onchange=e=>[...e.target.files].forEach(f=>{const r=new FileReader();r.onload=()=>{current.photos.push({id:uid(),data:r.result,note:''});saveCurrent();renderEditor();};r.readAsDataURL(f);});$('#recordBtn').onclick=toggleRecord;$('#generateSummaryBtn').onclick=generateSummary;$('#pdfBtn').onclick=()=>{saveCurrent();window.print();};$('#docBtn').onclick=exportDoc;$('#packageBtn').onclick=exportPackage;$('#shareBtn').onclick=share;$('#emailBtn').onclick=()=>{saveCurrent();location.href=`mailto:?subject=${encodeURIComponent(current.title)}&body=${encodeURIComponent(strip(current.summary)||current.note)}`;};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPrompt=e;$('#installBtn').classList.remove('hidden');});$('#installBtn').onclick=async()=>{if(deferredPrompt){deferredPrompt.prompt();await deferredPrompt.userChoice;deferredPrompt=null;$('#installBtn').classList.add('hidden');}};if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});

