const PROJECTS=[{id:'inbox',name:'Personal Workspace',color:'#0078d4'}]; // placeholder until the project data layer lands
const IC={chev:'<path d="M6 9l6 6 6-6"/>',overview:'<path d="M3 11l9-8 9 8"/><path d="M5 10v10h14V10"/>',meetings:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/>',tasks:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M8 12l3 3 5-6"/>',field:'<rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="9" cy="10" r="1.6"/><path d="M21 16l-5-5-8 8"/>'};
const SECTIONS=[{id:'overview',label:'Overview',icon:'overview'},{id:'meetings',label:'Meetings',icon:'meetings'},{id:'tasks',label:'Tasks',icon:'tasks'},{id:'field',label:'Field notes',icon:'field'}];
const navState={project:'inbox',section:'overview',expanded:true};
const svg=n=>`<svg class="ic" viewBox="0 0 24 24" aria-hidden="true">${IC[n]}</svg>`;
const sidebar=$('#sidebar'), narrowNav=matchMedia('(max-width:799px)');
function renderSidebar(){
  $('#projectList').innerHTML=PROJECTS.map(p=>{const sel=p.id===navState.project;return `<div class="proj${sel?' current':''}${sel&&navState.expanded?' open':''}"><button class="proj-head" data-project="${esc(p.id)}" title="${esc(p.name)}"><span class="proj-chip" style="--c:${esc(p.color)}">${esc(p.name.charAt(0).toUpperCase())}</span><span class="proj-name">${esc(p.name)}</span>${svg('chev').replace('class="ic"','class="ic chev"')}</button><nav class="proj-nav">${SECTIONS.map(s=>`<button class="nav-item${sel&&s.id===navState.section?' active':''}" data-sec="${s.id}" title="${s.label}">${svg(s.icon)}<span class="nav-label">${s.label}</span></button>`).join('')}</nav></div>`;}).join('');
}
function setNav(open){sidebar.classList.toggle('open',open);$('#scrim').classList.toggle('show',open&&narrowNav.matches);$('#menuBtn').setAttribute('aria-expanded',open);}
function showSection(sec){
  if(current){saveCurrent();current=null;$('#editorView').classList.add('hidden');$('#backBtn').classList.add('hidden');$('#newMeetingBtn').classList.remove('hidden');}
  navState.section=sec;const ov=sec==='overview',list=sec==='meetings',settings=sec==='settings';
  $('#overviewView').classList.toggle('hidden',!ov);$('#homeView').classList.toggle('hidden',!list);$('#placeholderView').classList.toggle('hidden',ov||list||settings);$('#settingsView').classList.toggle('hidden',!settings);
  if(ov)renderOverview();else if(list){renderMeetingsHead();renderHome($('#searchInput').value);}else if(!settings)renderSection(sec);
  renderSidebar();renderCrumbs();
}
$('#projectList').onclick=e=>{
  const nav=e.target.closest('.nav-item');
  if(nav){showSection(nav.dataset.sec);if(narrowNav.matches)setNav(false);return;}
  if(e.target.closest('.proj-head')){if(matchMedia('(min-width:600px) and (max-width:799px)').matches&&!sidebar.classList.contains('open')){setNav(true);return;}navState.expanded=!navState.expanded;renderSidebar();}
};
$('#menuBtn').onclick=()=>setNav(!sidebar.classList.contains('open'));
$('#sbClose').onclick=()=>setNav(false);$('#scrim').onclick=()=>setNav(false);
document.addEventListener('keydown',e=>{if(e.key==='Escape')setNav(false);});
narrowNav.addEventListener('change',()=>setNav(false));
renderSidebar();
$('#settingsNavBtn').onclick=()=>{showSection('settings');if(narrowNav.matches)setNav(false);};
$('#aiSettingsBtn').onclick=()=>showSection('settings');
$('#manageAiBtn').onclick=()=>showSection('settings');

/* ===== Project overview dashboard ===== */
Object.assign(IC,{folder:'<path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>',chevr:'<path d="M9 6l6 6-6 6"/>'});
const fmtD=v=>v?new Date(v).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'Not scheduled';
const ACTION_RE=/^\s*(?:✓\s*)?ACTION ITEM\s*:\s*(\[x\]\s*)?(.*)$/i;
function projectActions(){const out=[];meetings.forEach(m=>String(m.note||'').split('\n').forEach((line,i)=>{const r=line.match(ACTION_RE);if(r&&r[2].trim())out.push({mid:m.id,line:i,text:r[2].trim(),done:!!r[1],meeting:m});}));return out;}
function toggleAction(mid,i){const m=meetings.find(x=>x.id===mid);if(!m)return;const lines=String(m.note||'').split('\n');lines[i]=lines[i].replace(/(ACTION ITEM\s*:\s*)(\[x\]\s*)?/i,(all,p,x)=>x?p:p+'[x] ');m.note=lines.join('\n');persist();refreshSection();}
function renderCrumbs(){const p=PROJECTS.find(x=>x.id===navState.project)||PROJECTS[0],s=SECTIONS.find(x=>x.id===navState.section),c=svg('chevr');if(navState.section==='settings'){$('#crumbs').innerHTML=`${svg('overview')}${c}<b>Settings</b>`;return;}$('#crumbs').innerHTML=`${svg('overview')}${c}<span>Projects</span>${c}<button class="crumb" data-go="overview">${esc(p.name)}</button>${c}`+(current?`<button class="crumb" data-go="${s?.id||'overview'}">${s?.label||'Overview'}</button>${c}<b>${esc(current.title||'Untitled meeting')}</b>`:`<b>${s?.label||'Overview'}</b>`);}
function renderOverview(){
  const box=$('#overviewView');if(!box)return;
  const p=PROJECTS.find(x=>x.id===navState.project)||PROJECTS[0];
  const acts=projectActions(),open=acts.filter(a=>!a.done),done=acts.length-open.length;
  const photos=meetings.flatMap(m=>(m.photos||[]).map(ph=>({data:ph.data,note:ph.note,m})));
  const withPhotos=new Set(photos.map(x=>x.m.id)).size;
  const recent=[...meetings].sort((a,b)=>new Date(b.date||b.updated)-new Date(a.date||a.updated)).slice(0,5);
  const latest=[...photos].sort((a,b)=>b.m.updated-a.m.updated).slice(0,3);
  const nextActs=[...open,...acts.filter(a=>a.done)].slice(0,5);
  const stat=(cls,ic,label,num,sub,go)=>`<button class="stat ${cls}" data-go="${go}"><span class="stat-ic">${svg(ic)}</span><span class="stat-body"><span class="stat-label">${label}</span><br><span class="stat-num">${num}</span><br><span class="stat-sub">${sub}</span></span>${svg('chevr')}</button>`;
  const viewAll=go=>`<button class="link-btn" data-go="${go}">View all ${svg('chevr')}</button>`;
  const rows=recent.map(m=>{const n=acts.filter(a=>a.mid===m.id).length;return `<tr class="row" data-open="${m.id}"><td class="c-date">${fmtD(m.date)}</td><td><div class="t">${esc(m.title||'Untitled meeting')}</div><div class="s">${esc(m.location||'No location')}</div></td><td class="c-recap"><span class="pill ${m.summary?'ok':'no'}">${m.summary?'Recap ready':'No recap'}</span></td><td><span class="pill">${n}</span></td><td class="c-go">${svg('chevr')}</td></tr>`;}).join('');
  box.innerHTML=`
  <div class="ov-head"><span class="ov-icon">${svg('folder')}</span><div><h1>${esc(p.name)}</h1><p>Track meetings, actions and field notes for this project.</p></div></div>
  <div class="ov-stats">
    ${stat('blue','meetings','Meetings',meetings.length,'Total project meetings','meetings')}
    ${stat('amber','tasks','Open actions',open.length,done?`${done} completed`:'Nothing completed yet','tasks')}
    ${stat('green','field','Field photos',photos.length,photos.length?`Across ${withPhotos} meeting${withPhotos===1?'':'s'}`:'No photos yet','field')}
  </div>
  <div class="ov-grid">
    <section class="ov-card"><div class="ov-card-head"><h2>Recent meetings</h2>${viewAll('meetings')}</div>
      ${recent.length?`<table class="mt"><thead><tr><th class="c-date">Date</th><th>Title</th><th class="c-recap">Recap</th><th class="c-act">Actions</th><th class="c-go"></th></tr></thead><tbody>${rows}</tbody></table>`:`<div class="empty-note">No meetings yet. Capture your first one — agenda, notes and field photos all live here.<br><button class="primary" data-new>+ New meeting</button></div>`}
    </section>
    <div class="ov-col side">
      <section class="ov-card"><div class="ov-card-head"><h2>Next actions</h2>${viewAll('tasks')}</div>
        ${nextActs.length?nextActs.map(a=>`<label class="act${a.done?' done':''}"><input type="checkbox" data-mid="${a.mid}" data-line="${a.line}" ${a.done?'checked':''}><span><div class="act-t">${esc(a.text)}</div><div class="act-s">${esc(a.meeting.title||'Untitled meeting')} · ${fmtD(a.meeting.date)}</div></span></label>`).join(''):`<div class="empty-note">No action items yet. In a meeting, tap <b>✓ Action item</b> to add one.</div>`}
      </section>
      <section class="ov-card"><div class="ov-card-head"><h2>Latest field photos</h2>${viewAll('field')}</div>
        ${latest.length?`<div class="shots">${latest.map(x=>`<img src="${x.data}" alt="${esc(x.note||'Field photo')}" data-go="field">`).join('')}</div>`:`<div class="empty-note">No field photos yet. Add some from the Field notes tab inside a meeting.</div>`}
      </section>
    </div>
  </div>`;
}
$('#overviewView').addEventListener('click',e=>{
  const row=e.target.closest('[data-open]');if(row){openMeeting(row.dataset.open);return;}
  const go=e.target.closest('[data-go]');if(go){showSection(go.dataset.go);return;}
  if(e.target.closest('[data-new]'))$('#newMeetingDialog').showModal();
});
$('#overviewView').addEventListener('change',e=>{const c=e.target.closest('.act input');if(c)toggleAction(c.dataset.mid,+c.dataset.line);});
const _openMeeting=openMeeting;openMeeting=function(id){_openMeeting(id);if(current){$('#overviewView').classList.add('hidden');$('#placeholderView').classList.add('hidden');renderCrumbs();}};
const _renderHome=renderHome;renderHome=function(q){_renderHome(q);if(navState.section==='overview')renderOverview();};
$('#backBtn').onclick=()=>showSection(navState.section);

/* ===== Meetings / Tasks / Field notes sections ===== */
IC.chevl='<path d="M15 6l-6 6 6 6"/>';
let taskFilter='open';
const secHead=(title,desc)=>`<button class="back-link" data-go="overview">${svg('chevl')} Overview</button><div class="sec-head"><h1>${title}</h1><p>${desc}</p></div>`;
const byDateDesc=(a,b)=>new Date(b.date||b.updated)-new Date(a.date||a.updated);
function renderMeetingsHead(){$('#meetingsHead').innerHTML=secHead('Meetings','All meetings in this project. Open one to edit notes, agenda, photos and recap.');}
function renderTasks(){
  const box=$('#placeholderView'),acts=projectActions().sort((a,b)=>byDateDesc(a.meeting,b.meeting)),open=acts.filter(a=>!a.done).length;
  const list=acts.filter(a=>taskFilter==='all'||(taskFilter==='open'?!a.done:a.done));
  const tabs=[['open','Open',open],['done','Done',acts.length-open],['all','All',acts.length]].map(([k,l,n])=>`<button class="tab-pill${taskFilter===k?' active':''}" data-filter="${k}">${l} <span>${n}</span></button>`).join('');
  const empty=!acts.length?'No action items yet. In a meeting, tap <b>✓ Action item</b> in Notes to add one.':taskFilter==='open'?'All caught up — no open action items.':'Nothing here yet.';
  box.innerHTML=secHead('Tasks','Action items collected from the notes of every meeting in this project.')+`<div class="ov-card"><div class="pill-tabs">${tabs}</div>${list.length?list.map(a=>`<div class="task${a.done?' done':''}"><input type="checkbox" data-mid="${a.mid}" data-line="${a.line}" ${a.done?'checked':''} aria-label="Mark done"><button class="task-main" data-open="${a.mid}"><span class="act-t">${esc(a.text)}</span><span class="act-s">${esc(a.meeting.title||'Untitled meeting')} · ${fmtD(a.meeting.date)}${a.meeting.location?' · '+esc(a.meeting.location):''}</span></button></div>`).join(''):`<div class="empty-note">${empty}</div>`}</div>`;
}
function renderFieldNotes(){
  const box=$('#placeholderView'),photos=[...meetings].sort(byDateDesc).flatMap(m=>(m.photos||[]).map(ph=>({ph,m})));
  box.innerHTML=secHead('Field notes',photos.length?`${photos.length} photo${photos.length===1?'':'s'} from ${new Set(photos.map(x=>x.m.id)).size} meeting${new Set(photos.map(x=>x.m.id)).size===1?'':'s'}. Open one to edit its caption.`:'Photos and captions from your site visits.')+(photos.length?`<div class="tiles">${photos.map(({ph,m})=>`<button class="tile" data-open="${m.id}" data-tab="field"><img src="${ph.data}" alt="${esc(ph.note||'Field photo')}"><span class="tile-cap">${esc(ph.note||'No caption')}</span><span class="tile-meta">${esc(m.title||'Untitled meeting')} · ${fmtD(m.date)}</span></button>`).join('')}</div>`:`<div class="ov-card"><div class="empty-note">No field photos yet. Open a meeting and use the Field notes tab to take or attach photos.</div></div>`);
}
function renderSection(sec){if(sec==='tasks')renderTasks();else if(sec==='field')renderFieldNotes();}
function refreshSection(){if(navState.section==='overview')renderOverview();else renderSection(navState.section);}
const goClick=e=>{const g=e.target.closest('[data-go]');if(g){showSection(g.dataset.go);return true;}return false;};
$('#meetingsHead').addEventListener('click',goClick);
$('#crumbs').addEventListener('click',goClick);
$('#placeholderView').addEventListener('click',e=>{
  if(goClick(e))return;
  const f=e.target.closest('[data-filter]');if(f){taskFilter=f.dataset.filter;renderTasks();return;}
  const o=e.target.closest('[data-open]');if(o){activeTab=o.dataset.tab||'note';openMeeting(o.dataset.open);}
});
$('#placeholderView').addEventListener('change',e=>{const c=e.target.closest('.task input');if(c)toggleAction(c.dataset.mid,+c.dataset.line);});
showSection('overview');

/* ===== zMinutes local project data upgrade ===== */
const PROJECT_STORE='zminutes-projects-v1';
let projectData=[];
function loadProjects(){
  try{projectData=JSON.parse(localStorage.getItem(PROJECT_STORE)||'[]')}catch{projectData=[]}
  projectData=Array.isArray(projectData)?projectData.filter(p=>p&&typeof p==='object'&&typeof p.id==='string'&&p.id.trim()&&typeof p.name==='string'&&p.name.trim()):[];
  if(!projectData.length) projectData=[{id:'inbox',name:'Personal Workspace',color:'#0078d4',createdAt:Date.now()}];
  if(!projectData.some(p=>p.id==='inbox')) projectData.unshift({id:'inbox',name:'Personal Workspace',color:'#0078d4',createdAt:Date.now()});
  const inbox=projectData.find(p=>p.id==='inbox');if(inbox.name==='Inbox')inbox.name='Personal Workspace';
  let changed=false;meetings.forEach(m=>{if(!m.projectId||!projectData.some(p=>p.id===m.projectId)){m.projectId='inbox';changed=true}});
  try{localStorage.setItem(PROJECT_STORE,JSON.stringify(projectData))}catch(e){console.warn('Project browser-storage backup unavailable; continuing with in-memory and IndexedDB data.',e)}if(changed)try{localStorage.setItem('meeting-note-data',JSON.stringify(meetings))}catch(e){console.warn('Meeting browser-storage backup unavailable; continuing with in-memory data.',e)}
  PROJECTS.splice(0,PROJECTS.length,...projectData);
  if(!PROJECTS.some(p=>p.id===navState.project))navState.project='inbox';
}
function saveProjects(){try{localStorage.setItem(PROJECT_STORE,JSON.stringify(projectData))}catch(e){console.warn('Project backup unavailable; keeping data in IndexedDB.',e)}window.ZMinutesStore?.put('projects',projectData).catch(console.error);PROJECTS.splice(0,PROJECTS.length,...projectData)}
function activeMeetings(){return meetings.filter(m=>m.projectId===navState.project)}
function activeActions(){const out=[];activeMeetings().forEach(m=>String(m.note||'').split('\n').forEach((line,i)=>{const r=line.match(ACTION_RE);if(r&&r[2].trim())out.push({mid:m.id,line:i,text:r[2].trim(),done:!!r[1],meeting:m})}));return out}
function createProject(){const name=prompt('Project name');if(!name?.trim())return;const colors=['#0078d4','#8b5cf6','#14804a','#d4720a','#d13438'];projectData.push({id:uid(),name:name.trim(),color:colors[projectData.length%colors.length],createdAt:Date.now()});saveProjects();navState.project=projectData.at(-1).id;navState.expanded=true;showSection('overview')}
function selectProject(id){if(!PROJECTS.some(p=>p.id===id))return;navState.project=id;navState.expanded=true;showSection('overview')}
function renderSidebar(){
  $('#projectList').innerHTML=PROJECTS.map(p=>{const sel=p.id===navState.project;return `<div class="proj${sel?' current':''}${sel&&navState.expanded?' open':''}"><button class="proj-head" data-project="${esc(p.id)}" title="${esc(p.name)}"><span class="proj-chip" style="--c:${esc(p.color)}">${esc(p.name.charAt(0).toUpperCase())}</span><span class="proj-name">${esc(p.name)}</span>${svg('chev').replace('class="ic"','class="ic chev"')}</button><nav class="proj-nav">${SECTIONS.map(s=>`<button class="nav-item${sel&&s.id===navState.section?' active':''}" data-sec="${s.id}" title="${s.label}">${svg(s.icon)}<span class="nav-label">${s.label}</span></button>`).join('')}</nav></div>`}).join('');
  $('#settingsNavBtn')?.classList.toggle('active',navState.section==='settings');
}
function projectActions(){return activeActions()}
function renderHome(query=''){
  const list=$('#meetingList'),q=(query||'').toLowerCase(),items=activeMeetings().filter(m=>(m.title+m.location).toLowerCase().includes(q)).sort((a,b)=>new Date(b.updated)-new Date(a.updated));
  $('#meetingCount').textContent=items.length?`${items.length} meeting${items.length===1?'':'s'} in this project`:'No meetings in this project';list.innerHTML='';
  if(!items.length){list.innerHTML='<div class="empty-note">No meetings here yet. Use New meeting to start one.</div>';return}
  items.forEach(m=>{const t=$('#meetingTemplate').content.cloneNode(true),a=t.querySelector('.card-main');t.querySelector('.meeting-date').textContent=new Date(m.date||Date.now()).toLocaleDateString('en-US',{day:'2-digit',month:'short'});t.querySelector('strong').textContent=m.title||'Untitled meeting';t.querySelector('small').textContent=formatDate(m.date);a.onclick=()=>openMeeting(m.id);t.querySelector('.delete-btn').onclick=e=>{e.stopPropagation();if(confirm(`Delete “${m.title}”?`)){meetings=meetings.filter(x=>x.id!==m.id);persist();refreshSection()}};list.append(t)})
}
function renderOverview(){
 const box=$('#overviewView'),p=PROJECTS.find(x=>x.id===navState.project)||PROJECTS[0],items=activeMeetings(),acts=activeActions(),open=acts.filter(a=>!a.done),photos=items.flatMap(m=>(m.photos||[]).map(ph=>({ph,m}))),recent=[...items].sort((a,b)=>new Date(b.date||b.updated)-new Date(a.date||a.updated)).slice(0,5),latest=photos.slice(0,3);
 const stat=(c,i,l,n,s,g)=>`<button class="stat ${c}" data-go="${g}"><span class="stat-ic">${svg(i)}</span><span class="stat-body"><span class="stat-label">${l}</span><br><span class="stat-num">${n}</span><br><span class="stat-sub">${s}</span></span>${svg('chevr')}</button>`;
 const rows=recent.map(m=>`<tr class="row" data-open="${m.id}"><td class="c-date">${fmtD(m.date)}</td><td><div class="t">${esc(m.title||'Untitled meeting')}</div><div class="s">${esc(m.location||'No location')}</div></td><td class="c-recap"><span class="pill ${m.summary?'ok':'no'}">${m.summary?'Recap ready':'No recap'}</span></td><td><span class="pill">${acts.filter(a=>a.mid===m.id).length}</span></td><td class="c-go">${svg('chevr')}</td></tr>`).join('');
 box.innerHTML=`<div class="ov-head"><span class="ov-icon">${svg('folder')}</span><div><h1>${esc(p.name)}</h1><p>Track meetings, actions and field notes for this project.</p></div></div><div class="ov-stats">${stat('blue','meetings','Meetings',items.length,'Total project meetings','meetings')}${stat('amber','tasks','Open actions',open.length,acts.length-open.length?`${acts.length-open.length} completed`:'Nothing completed yet','tasks')}${stat('green','field','Field photos',photos.length,photos.length?`Across ${new Set(photos.map(x=>x.m.id)).size} meeting(s)`:'No photos yet','field')}</div><div class="ov-grid"><section class="ov-card"><div class="ov-card-head"><h2>Recent meetings</h2><button class="link-btn" data-go="meetings">View all ${svg('chevr')}</button></div>${recent.length?`<table class="mt"><thead><tr><th class="c-date">Date</th><th>Title</th><th class="c-recap">Recap</th><th class="c-act">Actions</th><th class="c-go"></th></tr></thead><tbody>${rows}</tbody></table>`:`<div class="empty-note">No meetings yet.<br><button class="primary" data-new>+ New meeting</button></div>`}</section><div class="ov-col side"><section class="ov-card"><div class="ov-card-head"><h2>Next actions</h2><button class="link-btn" data-go="tasks">View all ${svg('chevr')}</button></div>${open.length?open.slice(0,5).map(a=>`<label class="act"><input type="checkbox" data-mid="${a.mid}" data-line="${a.line}"><span><div class="act-t">${esc(a.text)}</div><div class="act-s">${esc(a.meeting.title||'Untitled meeting')}</div></span></label>`).join(''):'<div class="empty-note">No open action items.</div>'}</section><section class="ov-card"><div class="ov-card-head"><h2>Latest field photos</h2><button class="link-btn" data-go="field">View all ${svg('chevr')}</button></div>${latest.length?`<div class="shots">${latest.map(x=>`<img src="${x.ph.data}" alt="${esc(x.ph.note||'Field photo')}" data-go="field">`).join('')}</div>`:'<div class="empty-note">No field photos yet.</div>'}</section></div></div>`;
}
function renderTasks(){const box=$('#placeholderView'),acts=activeActions(),open=acts.filter(a=>!a.done).length;box.innerHTML=secHead('Tasks','Action items collected from meetings in this project.')+`<div class="ov-card">${acts.length?acts.map(a=>`<div class="task${a.done?' done':''}"><input type="checkbox" data-mid="${a.mid}" data-line="${a.line}" ${a.done?'checked':''}><button class="task-main" data-open="${a.mid}"><span class="act-t">${esc(a.text)}</span><span class="act-s">${esc(a.meeting.title||'Untitled meeting')} · ${fmtD(a.meeting.date)}</span></button></div>`).join(''):`<div class="empty-note">No action items in this project.</div>`}</div>`}
function renderFieldNotes(){const box=$('#placeholderView'),photos=activeMeetings().flatMap(m=>(m.photos||[]).map(ph=>({ph,m})));box.innerHTML=secHead('Field notes','Photos and captions from this project.')+(photos.length?`<div class="tiles">${photos.map(({ph,m})=>`<button class="tile" data-open="${m.id}" data-tab="field"><img src="${ph.data}" alt="${esc(ph.note||'Field photo')}"><span class="tile-cap">${esc(ph.note||'No caption')}</span><span class="tile-meta">${esc(m.title||'Untitled meeting')}</span></button>`).join('')}</div>`:`<div class="ov-card"><div class="empty-note">No field photos in this project.</div></div>`)}
function renderSection(sec){if(sec==='tasks')renderTasks();else if(sec==='field')renderFieldNotes();else if(sec==='files'){$('#placeholderView').innerHTML=secHead('Files','Exports and imported meeting packages remain available from each meeting.')+'<div class="ov-card"><div class="empty-note">Open a meeting to export its PDF, Word document, or meeting package.</div></div>'}}
const legacyNewMeeting=newMeeting;newMeeting=function(title='',date=nowLocal()){const before=meetings.length;legacyNewMeeting(title,date);if(meetings.length>before){meetings.at(-1).projectId=navState.project;persist()}}
const legacyImport=importPackage;importPackage=function(file){const reader=new FileReader();reader.onload=()=>{try{const m=JSON.parse(reader.result);m.id=uid();m.projectId=navState.project;m.updated=Date.now();meetings.push(m);persist();refreshSection();alert('Meeting imported into this project.')}catch{alert('This file is not a valid meeting package.')}};reader.readAsText(file)}
const legacyOpen=openMeeting;openMeeting=function(id){legacyOpen(id);if(!current)return;let pick=$('#projectPicker');if(!pick){pick=document.createElement('select');pick.id='projectPicker';pick.className='project-picker';$('#locationInput').after(pick);pick.onchange=()=>{current.projectId=pick.value;persist()}}pick.innerHTML=PROJECTS.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');pick.value=current.projectId||'inbox'}
$('#projectList').addEventListener('click',e=>{const h=e.target.closest('.proj-head');if(h){selectProject(h.dataset.project);if(narrowNav.matches)setNav(false)}});
const addProject=document.createElement('button');addProject.className='new-project';addProject.textContent='+ New project';addProject.onclick=createProject;document.querySelector('.sb-title')?.after(addProject);
SECTIONS.push({id:'files',label:'Files',icon:'folder'});loadProjects();renderSidebar();showSection('overview');
/* ===== zMinutes tasks, field notes and local calendar ===== */
const TASK_STORE='zminutes-tasks-v1', FIELD_STORE='zminutes-field-notes-v1';
let taskData=[],fieldData=[];
try{taskData=JSON.parse(localStorage.getItem(TASK_STORE)||'[]')}catch{taskData=[]}try{fieldData=JSON.parse(localStorage.getItem(FIELD_STORE)||'[]')}catch{fieldData=[]}
const saveTasks=()=>{try{localStorage.setItem(TASK_STORE,JSON.stringify(taskData))}catch(e){console.warn('Task backup unavailable; keeping data in IndexedDB.',e)}window.ZMinutesStore?.put('tasks',taskData).catch(console.error)};const saveFields=()=>{try{localStorage.setItem(FIELD_STORE,JSON.stringify(fieldData))}catch{try{localStorage.setItem(FIELD_STORE,JSON.stringify(fieldData.map(f=>({...f,photos:[]}))))}catch(e){console.warn('Field-note backup unavailable; keeping data in IndexedDB.',e)}}window.ZMinutesStore?.put('fieldNotes',fieldData).catch(console.error)};
if(!SECTIONS.some(s=>s.id==='calendar'))SECTIONS.splice(2,0,{id:'calendar',label:'Calendar',icon:'meetings'});
function taskLight(t){if(t.status==='done')return 'green';if(t.due&&new Date(t.due+'T23:59:59')<new Date())return 'red';return 'amber'}
function taskLabel(t){return t.status==='done'?'Completed':taskLight(t)==='red'?'Overdue':'In progress'}
function renderTasks(){const box=$('#placeholderView'),items=taskData.filter(t=>t.projectId===navState.project).sort((a,b)=>String(a.due||'9999').localeCompare(String(b.due||'9999')));box.innerHTML=secHead('Tasks','Plan the work, assign a due date, and follow the status at a glance.')+`<section class="task-create ov-card"><h2>Add a task</h2><form id="taskForm" class="task-form"><input id="taskTitle" required placeholder="What needs to be done?"><input id="taskDue" type="date"><button class="primary">+ Add task</button></form></section><section class="ov-card"><div class="ov-card-head"><h2>Project tasks</h2><span class="task-count">${items.length} total</span></div>${items.length?items.map(t=>`<article class="task-card"><span class="signal ${taskLight(t)}" title="${taskLabel(t)}"></span><div><strong>${esc(t.title)}</strong><small>${t.due?'Due '+new Date(t.due+'T00:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'No due date'} · ${taskLabel(t)}</small></div><select data-task-status="${t.id}"><option value="in-progress" ${t.status!=='done'?'selected':''}>In progress</option><option value="done" ${t.status==='done'?'selected':''}>Completed</option></select><button class="mini-delete" data-delete-task="${t.id}" aria-label="Delete task">×</button></article>`).join(''):'<div class="empty-note">No tasks yet. Add the first one above.</div>'}</section>`}
function renderFieldNotes(){const box=$('#placeholderView'),items=fieldData.filter(f=>f.projectId===navState.project).sort((a,b)=>b.updated-a.updated);box.innerHTML=secHead('Field notes','Capture site observations independently from a meeting.')+`<section class="field-create ov-card"><h2>New field note</h2><form id="fieldForm" class="field-form"><input id="fieldTitle" required placeholder="Observation title"><input id="fieldLocation" placeholder="Location"><textarea id="fieldText" placeholder="What did you observe? What needs follow-up?"></textarea><label class="field-upload">▧ Add photos <input id="fieldPhotos" type="file" accept="image/*" capture="environment" multiple hidden></label><div id="fieldPreview" class="field-preview"></div><button class="primary">+ Save field note</button></form></section><section class="ov-card"><div class="ov-card-head"><h2>Saved field notes</h2><span class="task-count">${items.length} total</span></div>${items.length?`<div class="field-list">${items.map(f=>`<article class="field-card"><div><h3>${esc(f.title)}</h3><p>${esc(f.location||'No location')} · ${new Date(f.updated).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</p><div class="field-text">${esc(f.text||'No description')}</div></div>${f.photos?.length?`<div class="field-card-photos">${f.photos.map(p=>`<img src="${p}" alt="${esc(f.title)}">`).join('')}</div>`:''}<button class="mini-delete" data-delete-field="${f.id}">×</button></article>`).join('')}</div>`:'<div class="empty-note">No field notes in this project.</div>'}</section>`}
function renderCalendar(){const box=$('#placeholderView'),items=activeMeetings().sort((a,b)=>new Date(a.date||0)-new Date(b.date||0)),tasks=taskData.filter(t=>t.projectId===navState.project);box.innerHTML=secHead('Calendar','Meetings and task deadlines in this project.')+`<section class="ov-card"><div class="calendar-toolbar"><h2>Upcoming schedule</h2><button id="icsBtn" class="link-btn">↓ Export .ics</button></div><div class="calendar-list">${[...items.map(m=>({date:m.date,type:'Meeting',title:m.title||'Untitled meeting',sub:m.location||'No location'})),...tasks.map(t=>({date:t.due,type:'Task',title:t.title,sub:taskLabel(t)}))].filter(x=>x.date).sort((a,b)=>new Date(a.date)-new Date(b.date)).map(x=>`<div class="calendar-item"><div class="calendar-date">${new Date(x.date).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</div><div><span class="calendar-type">${x.type}</span><strong>${esc(x.title)}</strong><small>${esc(x.sub)}</small></div></div>`).join('')||'<div class="empty-note">No scheduled meetings or task deadlines yet.</div>'}</div></section>`}
function renderSection(sec){if(sec==='tasks')renderTasks();else if(sec==='field')renderFieldNotes();else if(sec==='calendar')renderCalendar();else if(sec==='files'){$('#placeholderView').innerHTML=secHead('Files','Exports and imported meeting packages remain available from each meeting.')+'<div class="ov-card"><div class="empty-note">Open a meeting to export its PDF, Word document, or meeting package.</div></div>'}}
$('#placeholderView').addEventListener('submit',e=>{if(e.target.id==='taskForm'){e.preventDefault();taskData.push({id:uid(),projectId:navState.project,title:$('#taskTitle').value.trim(),due:$('#taskDue').value,status:'in-progress',created:Date.now()});saveTasks();renderTasks()}if(e.target.id==='fieldForm'){e.preventDefault();const photos=[...document.querySelectorAll('#fieldPreview img')].map(x=>x.src);fieldData.push({id:uid(),projectId:navState.project,title:$('#fieldTitle').value.trim(),location:$('#fieldLocation').value.trim(),text:$('#fieldText').value.trim(),photos,updated:Date.now()});saveFields();renderFieldNotes()}});
$('#placeholderView').addEventListener('change',e=>{const sel=e.target.closest('[data-task-status]');if(sel){const t=taskData.find(x=>x.id===sel.dataset.taskStatus);if(t){t.status=sel.value;saveTasks();renderTasks()}return}if(e.target.id==='fieldPhotos'){Promise.all([...e.target.files].map(f=>new Promise(done=>{const r=new FileReader();r.onload=()=>done(r.result);r.readAsDataURL(f)}))).then(imgs=>{$('#fieldPreview').innerHTML=imgs.map(x=>`<img src="${x}">`).join('')})}});
$('#placeholderView').addEventListener('click',e=>{const del=e.target.closest('[data-delete-task]');if(del){taskData=taskData.filter(t=>t.id!==del.dataset.deleteTask);saveTasks();renderTasks();return}const df=e.target.closest('[data-delete-field]');if(df){fieldData=fieldData.filter(f=>f.id!==df.dataset.deleteField);saveFields();renderFieldNotes();return}if(e.target.id==='icsBtn'){const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//zMinutes//EN'];activeMeetings().filter(m=>m.date).forEach(m=>{const d=new Date(m.date);const stamp=d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');lines.push('BEGIN:VEVENT',`UID:${m.id}@zminutes`,`DTSTART:${stamp}`,`SUMMARY:${String(m.title||'Meeting').replace(/[,;]/g,' ')}`,'END:VEVENT')});lines.push('END:VCALENDAR');download(new Blob([lines.join('\r\n')],{type:'text/calendar'}),`${safeName((PROJECTS.find(p=>p.id===navState.project)||{}).name||'zminutes')}.ics`)}});
renderSidebar();refreshSection();
